import { createInterface } from 'node:readline';
const lines = createInterface({ input: process.stdin });
lines.on('line', line => {
  let request;
  try { request = JSON.parse(line); } catch { return; }
  if (request.id === undefined) return;
  let result;
  if (request.method === 'initialize') result = {
    protocolVersion: request.params.protocolVersion,
    capabilities: { tools: {} }, serverInfo: { name: 'hello-plugin', version: '1.0.0' }
  };
  else if (request.method === 'tools/list') result = { tools: [{
    name: 'greet', description: 'Return a greeting without external side effects',
    inputSchema: { type: 'object', properties: { name: { type: 'string' } }, additionalProperties: false }
  }] };
  else if (request.method === 'tools/call' && request.params.name === 'greet') {
    const name = String(request.params.arguments?.name ?? 'world').slice(0, 100);
    result = { content: [{ type: 'text', text: `Hello, ${name}!` }] };
  } else if (request.method === 'ping') result = {};
  const response = result === undefined
    ? { jsonrpc: '2.0', id: request.id, error: { code: -32601, message: 'Method not found' } }
    : { jsonrpc: '2.0', id: request.id, result };
  process.stdout.write(JSON.stringify(response) + '\n');
});
